// {{BOT_NAME}} — task-specific ESKO reply and action-card engine.
import { findLocalAnswer } from './ai/site-knowledge.js';
import { analyzeIncomingText } from './ai/text-analysis.js';
import { generateConfiguredReply } from './ai/provider-adapter.js';

export const BOT_PROFILE = Object.freeze({
  id: '{{BOT_ID}}', name: '{{BOT_NAME}}', description: {{BOT_DESC_JSON}}, group: {{BOT_GROUP_JSON}},
  task: {{BOT_TASK_JSON}}, keywords: {{BOT_KEYWORDS_JSON}}, primaryReply: {{BOT_PRIMARY_REPLY_JSON}},
  platforms: {{BOT_PLATFORMS_JSON}}
});

const DEVELOPER_CHANNEL = process.env.ESKO_DEVELOPER_CHANNEL || 'https://whatsapp.com/channel/0029VbE7vGO4tRrwmz95M73S';
const SUPPORT_CHANNEL = process.env.ESKO_SUPPORT_CHANNEL || 'https://whatsapp.com/channel/0029VbE7vGO4tRrwmz95M73S';

export function supportChannel() { return SUPPORT_CHANNEL; }

export function buildActionCards() {
  const supportMessage = [
    '✍🏻لقد واجهتني مشكله', 'في هيكل هذا البوت', '♕معلومات البوت',
    'الاسم: ' + BOT_PROFILE.name, 'المعرّف: ' + BOT_PROFILE.id, 'القسم: ' + BOT_PROFILE.group,
    'المهمة: ' + BOT_PROFILE.task, 'الوصف: ' + BOT_PROFILE.description,
    'اتمني من المطور حل المشكله واشكر فريق الدعم', 'معا تحياتي'
  ].join('\n');
  const publicUrl = process.env.BOT_PUBLIC_URL || DEVELOPER_CHANNEL;
  return [
    { id: 'developer', title: 'قناة المطور', url: DEVELOPER_CHANNEL },
    { id: 'description', title: 'وصف البوت', text: BOT_PROFILE.description + ' — المهمة: ' + BOT_PROFILE.task, url: publicUrl },
    { id: 'support', title: 'الدعم الفني', url: supportChannel() },
    { id: 'usage', title: 'كيفية الاستخدام', text: 'اكتب /help للمساعدة. ابدأ برسالة واضحة تتعلق بمهمة البوت: ' + BOT_PROFILE.task, url: publicUrl }
  ];
}

export async function createReply(userText) {
  const text = String(userText || '').trim().slice(0, 3000);
  if (!text) return { text: 'اكتب رسالة أو سؤالًا واضحًا أولًا.', cards: buildActionCards() };
  if (/^(مساعدة|help|\/help)$/i.test(text)) return { text: 'طريقة الاستخدام: اكتب سؤالك المتعلق بمهمة البوت. استخدم /about للوصف و/privacy للخصوصية. لا يرسل هذا القالب رسائل غير مطلوبة.', cards: buildActionCards() };
  if (/^(وصف|about|description)$/i.test(text)) return { text: BOT_PROFILE.name + '\n' + BOT_PROFILE.description + '\nالمهمة: ' + BOT_PROFILE.task, cards: buildActionCards() };
  if (/^(privacy|خصوصية|\/privacy)$/i.test(text)) return { text: 'يعالج البوت الرسائل التي يبدأها المستخدم فقط. لا تشارك كلمات المرور أو الرموز السرية. راجع إعدادات الاستضافة والاحتفاظ بالبيانات قبل الاستخدام.', cards: buildActionCards() };

  const analysis = analyzeIncomingText(text);
  let answer = findLocalAnswer(text, BOT_PROFILE);
  if (process.env.AI_ENABLED === 'true') {
    const aiAnswer = await generateConfiguredReply({ text, profile: BOT_PROFILE, analysis });
    if (aiAnswer) answer = aiAnswer;
  }
  if (!answer) answer = 'وصلت رسالتك إلى ' + BOT_PROFILE.name + '. مهمة البوت: ' + BOT_PROFILE.task + '. أستطيع المساعدة داخل هذا النطاق؛ راجع النتائج قبل تنفيذ أي إجراء.';
  return { text: answer.slice(0, 3500), cards: buildActionCards() };
}

