// Conservative safeguards for {{BOT_NAME}}. No contact scraping or deletion.
const recentByUser = new Map();
const BLOCKED_SCHEMES = /^(javascript|data|file):/i;

export function cleanMessage(value) {
  return String(value ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '').trim().slice(0, 3000);
}

export function checkIncoming(userId, message) {
  const text = cleanMessage(message);
  if (!userId || !text) return { ok: false, reason: 'empty' };
  if (/(?:javascript|data|file):/i.test(text)) return { ok: false, reason: 'unsafe_link_scheme' };
  const now = Date.now();
  const last = recentByUser.get(String(userId)) || 0;
  if (now - last < 2500) return { ok: false, reason: 'rate_limited' };
  recentByUser.set(String(userId), now);
  if (recentByUser.size > 4000) {
    for (const [key, time] of recentByUser) if (now - time > 60000) recentByUser.delete(key);
  }
  return { ok: true, text };
}

export function inspectLinks(text) {
  const urls = String(text || '').match(/(?:https?:\/\/|javascript:|data:|file:)[^\s]*/gi) || [];
  const blocked = urls.filter(value => BLOCKED_SCHEMES.test(value) || value.length > 500);
  return { urls, blocked, safe: blocked.length === 0 };
}

export function warnAdmin(reason, userId) {
  // Connect this callback to a private admin log on your own server.
  console.warn('[ESKO SECURITY]', { reason, userId: String(userId || '').slice(0, 40), at: new Date().toISOString() });
}

