// Official WhatsApp Business Cloud API adapter. Incoming user messages only.
import { BOT_PROFILE } from './core.js';

export async function sendWhatsAppMessage(to, reply) {
  const token = process.env.WHATSAPP_ACCESS_TOKEN;
  const phoneId = process.env.WHATSAPP_PHONE_NUMBER_ID;
  const version = process.env.WHATSAPP_GRAPH_VERSION;
  if (!token || !phoneId || !version) throw new Error('WhatsApp Cloud API environment is incomplete');
  const cards = (reply.cards || []).map((card, index) => {
    const detail = card.text ? ' — ' + card.text : '';
    return '🟩 ' + (index + 1) + '. ' + card.title + detail + (card.url ? '\n' + card.url : '');
  }).join('\n\n');
  const bodyText = (reply.text + '\n\n' + cards).slice(0, 4000);
  const response = await fetch(`https://graph.facebook.com/${version}/${phoneId}/messages`, {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: true, body: bodyText } }),
    signal: AbortSignal.timeout(15000)
  });
  if (!response.ok) throw new Error('WhatsApp API HTTP ' + response.status + ': ' + (await response.text()).slice(0, 400));
  return response.json();
}

export function extractWhatsAppMessages(payload) {
  const output = [];
  for (const entry of payload?.entry || []) for (const change of entry?.changes || []) {
    for (const message of change?.value?.messages || []) {
      if (message.type === 'text' && message.text?.body) output.push({ from: message.from, text: message.text.body, id: message.id });
    }
  }
  return output;
}

