// Official Telegram Bot API adapter. Set TELEGRAM_BOT_TOKEN on the server only.
export async function sendTelegramMessage(chatId, reply) {
  const token = process.env.TELEGRAM_BOT_TOKEN;
  if (!token) throw new Error('TELEGRAM_BOT_TOKEN is not configured');
  const keyboard = (reply.cards || []).map(card => [{
    text: card.title,
    url: card.url || (process.env.BOT_PUBLIC_URL || process.env.ESKO_DEVELOPER_CHANNEL)
  }]);
  const response = await fetch('https://api.telegram.org/bot' + token + '/sendMessage', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, text: reply.text, reply_markup: { inline_keyboard: keyboard } }),
    signal: AbortSignal.timeout(15000)
  });
  const data = await response.json();
  if (!response.ok || !data.ok) throw new Error('Telegram API rejected the message');
  return data.result;
}

