async function readBody(req) {
  const chunks = []; let size = 0;
  for await (const chunk of req) { size += chunk.length; if (size > 1024 * 1024) throw new Error('Request too large'); chunks.push(chunk); }
  return Buffer.concat(chunks);
}
function verifyWhatsAppSignature(raw, header) {
  if (!APP_SECRET) return false;
  const expected = 'sha256=' + createHmac('sha256', APP_SECRET).update(raw).digest('hex');
  const a = Buffer.from(expected); const b = Buffer.from(String(header || ''));
  return a.length === b.length && timingSafeEqual(a, b);
}
function json(res, code, value) { const data = Buffer.from(JSON.stringify(value)); res.writeHead(code, { 'Content-Type':'application/json; charset=utf-8', 'Content-Length':data.length, 'Cache-Control':'no-store' }); res.end(data); }

const server = createServer(async (req, res) => {
  const url = new URL(req.url || '/', 'http://localhost');
  try {
    if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { ok:true, bot:'{{BOT_NAME}}', time:new Date().toISOString() });
    if (req.method === 'GET' && url.pathname === '/webhook/whatsapp') {
      const mode = url.searchParams.get('hub.mode');
      const token = url.searchParams.get('hub.verify_token');
      const challenge = url.searchParams.get('hub.challenge');
      if (mode === 'subscribe' && VERIFY && token === VERIFY) {
        if (!whatsappConnectedLogged) { whatsappConnectedLogged = true; connectionBanner('WhatsApp Business Cloud API'); }
        res.writeHead(200, { 'Content-Type':'text/plain' }); return res.end(challenge || '');
      }
      return json(res, 403, { ok:false, error:'Webhook verification failed' });
    }
    if (req.method === 'POST' && url.pathname === '/webhook/whatsapp') {
      const raw = await readBody(req);
      if (!verifyWhatsAppSignature(raw, req.headers['x-hub-signature-256'])) return json(res, 401, { ok:false });
      const payload = JSON.parse(raw.toString('utf8'));
      for (const message of extractWhatsAppMessages(payload)) {
        const checked = checkIncoming(message.from, message.text);
        if (!checked.ok) { warnAdmin(checked.reason, message.from); continue; }
        const reply = await createReply(checked.text);
        await sendWhatsAppMessage(message.from, reply);
        console.log('\x1b[92mتم استقبال رسالة WhatsApp والرد عليها عبر Cloud API\x1b[0m');
      }
      return json(res, 200, { ok:true });
    }
    if (req.method === 'POST' && url.pathname === '/webhook/telegram') {
      if (!TELEGRAM_SECRET || req.headers['x-telegram-bot-api-secret-token'] !== TELEGRAM_SECRET) return json(res, 401, { ok:false });
      if (!telegramConnectedLogged) { telegramConnectedLogged = true; connectionBanner('Telegram Bot API'); }
      const raw = await readBody(req); const update = JSON.parse(raw.toString('utf8'));
      const message = update.message;
      if (message?.chat?.id && message?.text) {
        const checked = checkIncoming(message.from?.id, message.text);
        if (checked.ok) await sendTelegramMessage(message.chat.id, await createReply(checked.text));
        else warnAdmin(checked.reason, message.from?.id);
      }
      return json(res, 200, { ok:true });
    }
    return json(res, 404, { ok:false, error:'Not found' });
  } catch (error) {
    console.error('[ESKO ERROR]', error.message);
    return json(res, 500, { ok:false, error:'Internal server error' });
  }
});

banner();
server.listen(PORT, () => console.log('\x1b[92mتم تشغيل خادم ESKO على المنفذ ' + PORT + ' — بانتظار Webhook رسمي.\x1b[0m'));

