// Official Discord REST API adapter. It sends an embed and four link buttons.
export async function sendDiscordMessage(channelId, reply) {
  const token = process.env.DISCORD_BOT_TOKEN;
  if (!token || !channelId) throw new Error('Discord bot token or channel id is missing');
  const components = (reply.cards || []).map(card => ({ type: 2, style: 5, label: String(card.title).slice(0, 80), url: card.url }));
  const response = await fetch('https://discord.com/api/v10/channels/' + channelId + '/messages', {
    method: 'POST',
    headers: { Authorization: 'Bot ' + token, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      content: String(reply.text || '').slice(0, 1800),
      embeds: [{ color: 0x20c879, title: '{{BOT_NAME}}', description: '{{BOT_DESC}}'.slice(0, 3500) }],
      components: components.length ? [{ type: 1, components }] : []
    }),
    signal: AbortSignal.timeout(15000)
  });
  if (!response.ok) throw new Error('Discord API HTTP ' + response.status);
  return response.json();
}

