// Local task-specific replies. No network calls and no credentials.
export function findLocalAnswer(text, profile) {
  const q = String(text || '').toLowerCase();
  const keywords = Array.isArray(profile?.keywords) ? profile.keywords : [];
  const matched = keywords.some(word => String(word).length > 1 && q.includes(String(word).toLowerCase()));
  return matched ? String(profile?.primaryReply || '') : '';
}

