// Small local text analyser used by every ESKO bot blueprint.
export function analyzeIncomingText(text) {
  const value = String(text || '').trim().slice(0, 3000);
  const words = value.split(/\s+/).filter(Boolean);
  const mentionsSupport = /help|مساعدة|دعم|مشكلة|مشكل|support/i.test(value);
  const question = /[؟?]|كيف|ماذا|لماذا|هل|متى|أين/.test(value);
  const freq = new Map();
  for (const word of words) {
    const clean = word.replace(/[^\p{L}\p{N}]/gu, '').toLowerCase();
    if (clean.length > 2) freq.set(clean, (freq.get(clean) || 0) + 1);
  }
  const keywords = [...freq.entries()].sort((a,b) => b[1]-a[1]).slice(0,5).map(([word]) => word);
  return { wordCount: words.length, isQuestion: question, needsSupport: mentionsSupport, keywords };
}

