// Optional server-side OpenAI-compatible adapter. Keep API keys in .env on the server.
export async function generateConfiguredReply({ text, profile, analysis }) {
  if (process.env.AI_ENABLED !== 'true') return '';
  const url = process.env.AI_API_URL;
  const key = process.env.AI_API_KEY;
  const model = process.env.AI_MODEL;
  if (!url || !key || !model) return '';
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + key },
    body: JSON.stringify({
      model,
      messages: [
        { role: 'system', content: 'أنت مساعد مفيد ومحترم. اسم البوت: ' + profile.name + '. المهمة: ' + profile.task + '. الوصف: ' + profile.description + '. التزم بوظيفة هذا البوت فقط، ولا تطلب كلمات مرور أو رموز سرية، ولا تنفذ إجراءات حساسة دون موافقة.' },
        { role: 'user', content: String(text).slice(0, 3000) + '\n\nتحليل محلي: ' + JSON.stringify(analysis) }
      ]
    }),
    signal: AbortSignal.timeout(12000)
  });
  if (!response.ok) throw new Error('AI provider returned HTTP ' + response.status);
  const payload = await response.json();
  return String(payload.choices?.[0]?.message?.content || '').trim().slice(0, 3500);
}
